export async function managementPanel(c){
 const {api,esc,fmt,form,input}=c,a=await api('management');
 const mf=(action,fields,button)=>form(action,fields,button,'data-management="true"');
 const target=input('Hesap no','target','number','','required min="1"');
 const roomSelect='<label>Oda<select name="room">'+a.rooms.map(r=>`<option value="${esc(r.id)}">${esc(r.id)}${r.closed?' · Kapalı':''}</option>`).join('')+'</select></label>';
 return `<h2>Yönetici Paneli</h2><div class="metric-row"><div class="metric">Hesap<strong>${a.stats.accounts}</strong></div><div class="metric">Bağlantı<strong>${a.stats.online}</strong></div><div class="metric">Etkin oda<strong>${a.stats.activeRooms}</strong></div></div>
 <div class="profile-columns"><section class="sub-card"><h3>Oda ayarları</h3>${mf('room',roomSelect+input('Yeni turların başlangıç ödülü','basePrize','number','50000','required min="0" max="100000000"')+input('Bu turun ödülüne ekle','extraPrize','number','0','required min="0" max="100000000"')+'<label>Giriş durumu<select name="closed"><option value="false">Açık</option><option value="true">Yeni girişlere kapalı</option></select></label>','Oda ayarlarını kaydet')}<p class="subtle">Süreler sabit takvimle devam eder. Kapalı oda mevcut oyuncuları oyundan çıkarmaz.</p></section>
 <section class="sub-card"><h3>Turu elle bitir</h3>${mf('finishRoom',roomSelect,'Kazananı belirle ve yeni tura geç')}<h3>Genel duyuru</h3>${mf('announce','<label>Duyuru<textarea name="text" required maxlength="300"></textarea></label>','Tüm odalara duyur')}</section></div>
 <div class="profile-columns"><section class="sub-card"><h3>Gold / Bonus düzenle</h3>${mf('wallet',target+'<label>Bakiye<select name="wallet"><option value="gold">Gold</option><option value="bonus">Bonus Gold</option></select></label>'+input('Tutar (eksi değer düşürür)','amount','number','10000','required min="-100000000" max="100000000"')+input('İşlem nedeni','reason','text','','required maxlength="200"'),'Bakiyeyi güncelle')}</section>
 <section class="sub-card"><h3>Premium yönetimi</h3>${mf('premium',target+input('Gün (0 = Premium kaldır)','days','number','7','required min="0" max="365"'),'Premium uygula')}</section></div>
 <div class="profile-columns"><section class="sub-card"><h3>Sohbet susturma</h3>${mf('mute',target+input('Saat (0 = susturmayı kaldır)','hours','number','1','required min="0" max="8760"'),'Susturmayı uygula')}<h3>Oyundan çıkar</h3>${mf('kick',target,'Bağlantıyı kapat')}</section>
 <section class="sub-card"><h3>Tek kullanımlık PIN üret</h3>${mf('pin','<label>Tür<select name="kind"><option value="gold">Gold</option><option value="premium">Premium gün</option></select></label>'+input('Miktar / gün','amount','number','10000','required min="1" max="100000000"'),'PIN oluştur')}<p class="subtle">Kod yalnızca oluşturulduğunda gösterilir. Yönetici işlemleri denetim kaydına yazılır.</p></section></div>
 <h3>Oyuncular · son 200 hesap</h3><table class="data-table"><thead><tr><th>HESAP</th><th>İSİM</th><th>GOLD</th><th>BONUS</th><th>DURUM</th></tr></thead><tbody>${a.users.map(u=>`<tr><td>#${u.id}</td><td>${esc(u.name)}</td><td>${fmt(u.gold)}</td><td>${fmt(u.bonus)}</td><td>${u.bannedUntil>Date.now()?'Kısıtlı':u.mutedUntil>Date.now()?'Susturuldu':u.role==='admin'?'Yönetici':'Oyuncu'}</td></tr>`).join('')}</tbody></table>
 <h3>Oda durumu</h3><table class="data-table"><thead><tr><th>ODA</th><th>GİRİŞ</th><th>OYUNCU</th><th>ÖDÜL</th></tr></thead><tbody>${a.rooms.map(r=>`<tr><td>${esc(r.id)}</td><td>${r.closed?'Kapalı':'Açık'}</td><td>${r.players}</td><td>${fmt(r.base_prize)}</td></tr>`).join('')}</tbody></table>
 <h3>Oyuncu şikayetleri</h3>${a.reports.map(r=>`<section class="sub-card"><b>#${r.id} · #${r.reporter} → #${r.target} · ${esc(r.status)}</b><p>${esc(r.text)}</p>${mf('reportStatus','<input type="hidden" name="target" value="'+r.id+'"><label>Durum<select name="status"><option>Açık</option><option>İnceleniyor</option><option>Çözüldü</option></select></label>','Durumu kaydet')}</section>`).join('')||'<p>Şikayet yok.</p>'}`;
}
